static void Check(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
template<class Fence> static void Wait(Fence* fence,uint64_t value){if(fence->GetCompletedValue()>=value)return;const auto event=CreateEventW(nullptr,FALSE,FALSE,nullptr);Check(event!=nullptr,"Fence event unavailable");const auto result=fence->SetEventOnCompletion(value,event);const auto waited=SUCCEEDED(result)?WaitForSingleObject(event,5000):WAIT_FAILED;CloseHandle(event);Check(waited==WAIT_OBJECT_0,"GPU fence did not complete");}
