    uint8_t* bytes{};D3D12_RANGE range{0,size_t(total)};Need(readback->Map(0,&range,reinterpret_cast<void**>(&bytes)),"Fixture readback map failed");const auto inside=bytes+26*footprint.Footprint.RowPitch+26*4;Pixels(inside,bytes,tenBit);const D3D12_RANGE written{0,0};readback->Unmap(0,&written);
