    const auto window11=CreateWindowExW(0,L"STATIC",L"Private DX11 overlay fixture",WS_OVERLAPPEDWINDOW,0,0,640,480,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);Check(window11!=nullptr,"DX11 fixture window unavailable");
