    ComPtr<ID3D11Texture2D> back11;ComPtr<ID3D11RenderTargetView> target11;Need(swap11->GetBuffer(0,IID_PPV_ARGS(&back11)),"DX11 fixture buffer unavailable");Need(device11->CreateRenderTargetView(back11.Get(),nullptr,&target11),"DX11 fixture view unavailable");context11->ClearRenderTargetView(target11.Get(),blue);
    nonce[0]=nonce[0]=='a'?'b':'a';producer.Create(device11.Get(),GetCurrentProcessId(),nonce,256,128);producer.Page->Left=16;producer.Page->Top=16;producer.Page->Opacity=10000;
